function validate([arr, target]) {
  if (arr.length < 1 || arr.length > 10000) return 'arr needs 1 to 10^4 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value in arr is a whole number from 1 to 10^5.';
  if (!Number.isInteger(target) || target < 1 || target > 100000) return 'target is a whole number from 1 to 10^5.';
  return null;
}

