function findBestValue(arr, target) {
  const cappedSum = (value) => {
    let sum = 0;
    for (const num of arr) {
      sum += Math.min(num, value);
    }
    return sum;
  };

  let left = 0;
  let right = Math.max(...arr);
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (cappedSum(mid) < target) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  // left is the smallest cap whose sum reaches target, or the largest element if none does.
  const above = Math.abs(cappedSum(left) - target);
  const below = Math.abs(cappedSum(left - 1) - target);
  return below <= above ? left - 1 : left;
}

