function findBestValue(arr, target) {
  // Caps above the largest element change nothing, so try every cap from 0 up to it.
  let largest = 0;
  for (const num of arr) if (num > largest) largest = num;
  let best = 0;
  let bestGap = Infinity;
  for (let value = 0; value <= largest; value++) {
    let sum = 0;
    for (const num of arr) sum += num > value ? value : num;
    const gap = Math.abs(sum - target);
    if (gap < bestGap) {
      bestGap = gap;
      best = value;
    }
  }
  return best;
}

